"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass

ONE_DAY = dt.timedelta(days=1)


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: dt.datetime    # aware, in the rule's zone
    end: dt.datetime


def _months_between(a, b):
    return (b.year - a.year) * 12 + (b.month - a.month)


def _matches(rule, day):
    """Is `day` one of the rule's dates?"""
    if rule.unit == "day":
        return (day - rule.start).days % rule.every == 0
    if rule.unit == "week":
        weeks = (day - rule.start).days // 7
        return weeks % rule.every == 0 and day.weekday() in rule.on
    if _months_between(rule.start, day) % rule.every != 0:
        return False
    month_len = calendar.monthrange(day.year, day.month)[1]
    for item in rule.on:
        wanted = month_len if item == "last" else min(item, month_len)
        if day.day == wanted:
            return True
    return False


def expand(ruledef, not_after):
    """Yield the rule's occurrences in order, up to the local date `not_after`."""
    rule = ruledef.rule
    length = dt.timedelta(minutes=rule.minutes)
    day = rule.start
    while day <= not_after:
        if rule.until and day >= rule.until:
            break
        if _matches(rule, day):
            for time in rule.at:
                start = dt.datetime.combine(day, time, tzinfo=ruledef.tz)
                key = f"{day.isoformat()}T{time.strftime('%H:%M')}"
                yield Occurrence(ruledef, key, start, start + length)
        day += ONE_DAY
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
from dataclasses import dataclass
from zoneinfo import ZoneInfo

from .errors import PlanError, RuleSyntaxError
from .rules import Rule, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int


@dataclass
class Override:
    rule: str
    key: str
    action: str
    to: dt.datetime = None
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # (rule id, key) -> Override
    min_segment: int


def _zone(name):
    try:
        return ZoneInfo(name)
    except Exception:
        raise PlanError(f"unknown timezone {name!r}")


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    rules = []
    for index, item in enumerate(raw.get("rules", [])):
        rid = item.get("id")
        if not rid:
            raise PlanError(f"rule #{index} has no id")
        try:
            rule = parse_rule(item["rule"])
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position)
        tz = _zone(item["timezone"]) if item.get("timezone") else default_tz
        rules.append(RuleDef(index, rid, rule, tz, item.get("priority", 0)))

    ids = {r.id for r in rules}
    overrides = {}
    for item in raw.get("overrides", []):
        rid, key, action = item.get("rule"), item.get("key"), item.get("action")
        if rid not in ids:
            raise PlanError(f"override for unknown rule {rid!r}")
        if action not in ("cancel", "move"):
            raise PlanError(f"rule {rid}: unknown override action {action!r}")
        ov = Override(rid, key, action)
        if action == "move":
            try:
                ov.to = dt.datetime.fromisoformat(item["to"])
            except (KeyError, ValueError, TypeError):
                raise PlanError(f"rule {rid}: move override needs a valid 'to'")
            if item.get("for"):
                ov.minutes = parse_duration(item["for"])
        overrides[(rid, key)] = ov

    min_segment = parse_duration(raw["min_segment"]) if raw.get("min_segment") else 0
    return Plan(rules, overrides, min_segment)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt

from .errors import PlanError
from .expand import expand
from .plan import load_plan


def _parse_bound(text, default_tz):
    try:
        value = dt.datetime.fromisoformat(text.replace("Z", "+00:00"))
    except (ValueError, AttributeError):
        raise PlanError(f"invalid date-time {text!r}")
    if value.tzinfo is None:
        value = value.replace(tzinfo=default_tz)
    return value


def _collect(plan, start, end):
    found = []
    for ruledef in plan.rules:
        count = 0
        for occ in expand(ruledef, end.astimezone(ruledef.tz).date()):
            override = plan.overrides.get((ruledef.id, occ.key))
            if override and override.action == "cancel":
                continue
            count += 1
            if ruledef.rule.times and count > ruledef.rule.times:
                break
            if not (start <= occ.start < end):
                continue
            if override and override.action == "move":
                length = occ.end - occ.start
                if override.minutes:
                    length = dt.timedelta(minutes=override.minutes)
                occ.start = override.to.replace(tzinfo=ruledef.tz)
                occ.end = occ.start + length
            found.append(occ)
    return found


def _as_dict(occ):
    return {
        "rule": occ.rule.id,
        "key": occ.key,
        "start": occ.start.isoformat(timespec="seconds"),
        "end": occ.end.isoformat(timespec="seconds"),
    }


def occurrences(plan, start, end):
    plan_obj = load_plan(plan)
    default_tz = plan_obj.rules[0].tz if plan_obj.rules else dt.timezone.utc
    lo, hi = _parse_bound(start, default_tz), _parse_bound(end, default_tz)
    rows = [_as_dict(occ) for occ in _collect(plan_obj, lo, hi)]
    rows.sort(key=lambda row: (row["start"], row["end"]))
    return rows


